Dataspatium.assets.register("presets/api/vedur-observations.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"vedur-observations\",\n  \"name\": \"Veðurstofa Íslands: väderobservationer\",\n  \"publisher\": \"Veðurstofa Íslands (Icelandic Met Office)\",\n  \"description\": \"Senaste observationer från Islands väderstationer: temperatur (T), vindhastighet (F), vindriktning (D), byvind (FX, FG), nederbörd (R), väder (W) och sikt (V). Stationsnummer finns på vedur.is under Stöðvar; 1 = Reykjavík, 422 = Akureyri, 571 = Egilsstaðaflugvöllur, 990 = Keflavíkurflugvöllur.\",\n  \"docs\": \"https://www.vedur.is/media/vedurstofan/XMLthjonusta.pdf\",\n  \"license\": { \"name\": \"Fri att använda med källangivelse (Veðurstofa Íslands)\", \"url\": \"https://www.vedur.is/um-vi/vefurinn/\" },\n  \"level\": 1,\n  \"country\": \"IS\",\n  \"baseUrl\": \"https://xmlweather.vedur.is\",\n  \"auth\": { \"type\": \"none\" },\n  \"rateLimit\": { \"requests\": 2, \"perSeconds\": 1 },\n  \"endpoints\": [\n    {\n      \"id\": \"obs\",\n      \"name\": \"Observationer\",\n      \"description\": \"En rad per station med den senaste observationen.\",\n      \"method\": \"GET\",\n      \"path\": \"/\",\n      \"params\": [\n        { \"name\": \"op_w\", \"in\": \"query\", \"type\": \"string\", \"default\": \"xml\", \"hidden\": true },\n        { \"name\": \"type\", \"in\": \"query\", \"type\": \"string\", \"default\": \"obs\", \"hidden\": true },\n        { \"name\": \"view\", \"in\": \"query\", \"type\": \"string\", \"default\": \"xml\", \"hidden\": true },\n        { \"name\": \"ids\", \"in\": \"query\", \"label\": \"Stationsnummer (semikolon mellan)\", \"type\": \"string\", \"required\": true, \"example\": \"1;422;571;990\" },\n        { \"name\": \"params\", \"in\": \"query\", \"label\": \"Parametrar (semikolon mellan, tomt ger alla)\", \"type\": \"string\", \"example\": \"T;D;F\" },\n        { \"name\": \"lang\", \"in\": \"query\", \"label\": \"Språk\", \"type\": \"enum\", \"default\": \"en\", \"options\": [{ \"value\": \"is\", \"label\": \"Isländska\" }, { \"value\": \"en\", \"label\": \"Engelska\" }] }\n      ],\n      \"response\": { \"format\": \"xml\", \"recordTag\": \"station\", \"rename\": { \"@id\": \"station_id\", \"@valid\": \"valid\", \"name\": \"station\" }, \"drop\": [\"link\", \"err\"] },\n      \"dataset\": { \"name\": \"Veðurstofa observationer {ids}\", \"keys\": [\"station_id\", \"time\"] }\n    }\n  ],\n  \"notes\": \"Ange källa: Veðurstofa Íslands.\",\n  \"i18n\": {\n    \"en\": { \"name\": \"Icelandic Met Office: weather observations\", \"publisher\": \"Icelandic Met Office (Veðurstofa Íslands)\", \"description\": \"Latest observations from Iceland's weather stations: temperature (T), wind speed (F), wind direction (D), gusts (FX, FG), precipitation (R), weather (W) and visibility (V). Station numbers are listed on vedur.is under Stöðvar; 1 = Reykjavík, 422 = Akureyri, 571 = Egilsstaðir airport, 990 = Keflavík airport.\", \"notes\": \"Cite the source: Icelandic Met Office.\", \"endpoints\": { \"obs\": { \"name\": \"Observations\", \"description\": \"One row per station with the latest observation.\", \"params\": { \"ids\": { \"label\": \"Station numbers (semicolons between)\" }, \"params\": { \"label\": \"Parameters (semicolons between, empty gives all)\" }, \"lang\": { \"label\": \"Language\", \"options\": { \"is\": \"Icelandic\", \"en\": \"English\" } } } } }, \"dataset\": { \"obs\": \"Icelandic Met Office observations {ids}\" } },\n    \"da\": { \"name\": \"Veðurstofa Íslands: vejrobservationer\", \"publisher\": \"Veðurstofa Íslands (Islands meteorologiske institut)\", \"description\": \"Seneste observationer fra Islands vejrstationer: temperatur (T), vindhastighed (F), vindretning (D), vindstød (FX, FG), nedbør (R), vejr (W) og sigtbarhed (V). Stationsnumre findes på vedur.is under Stöðvar; 1 = Reykjavík, 422 = Akureyri, 571 = Egilsstaðir lufthavn, 990 = Keflavík lufthavn.\", \"notes\": \"Angiv kilde: Veðurstofa Íslands.\", \"endpoints\": { \"obs\": { \"name\": \"Observationer\", \"description\": \"Én række pr. station med den seneste observation.\", \"params\": { \"ids\": { \"label\": \"Stationsnumre (semikolon imellem)\" }, \"params\": { \"label\": \"Parametre (semikolon imellem, tomt giver alle)\" }, \"lang\": { \"label\": \"Sprog\", \"options\": { \"is\": \"Islandsk\", \"en\": \"Engelsk\" } } } } }, \"dataset\": { \"obs\": \"Veðurstofa observationer {ids}\" } },\n    \"nb\": { \"name\": \"Veðurstofa Íslands: værobservasjoner\", \"publisher\": \"Veðurstofa Íslands (Islands meteorologiske institutt)\", \"description\": \"Siste observasjoner fra Islands værstasjoner: temperatur (T), vindhastighet (F), vindretning (D), vindkast (FX, FG), nedbør (R), vær (W) og sikt (V). Stasjonsnumre finnes på vedur.is under Stöðvar; 1 = Reykjavík, 422 = Akureyri, 571 = Egilsstaðir lufthavn, 990 = Keflavík lufthavn.\", \"notes\": \"Oppgi kilde: Veðurstofa Íslands.\", \"endpoints\": { \"obs\": { \"name\": \"Observasjoner\", \"description\": \"Én rad per stasjon med den siste observasjonen.\", \"params\": { \"ids\": { \"label\": \"Stasjonsnumre (semikolon mellom)\" }, \"params\": { \"label\": \"Parametere (semikolon mellom, tomt gir alle)\" }, \"lang\": { \"label\": \"Språk\", \"options\": { \"is\": \"Islandsk\", \"en\": \"Engelsk\" } } } } }, \"dataset\": { \"obs\": \"Veðurstofa observasjoner {ids}\" } },\n    \"fi\": { \"name\": \"Islannin ilmatieteen laitos: säähavainnot\", \"publisher\": \"Veðurstofa Íslands (Islannin ilmatieteen laitos)\", \"description\": \"Viimeisimmät havainnot Islannin sääasemilta: lämpötila (T), tuulen nopeus (F), tuulen suunta (D), puuskat (FX, FG), sade (R), sää (W) ja näkyvyys (V). Asemanumerot löytyvät vedur.is-sivustolta kohdasta Stöðvar; 1 = Reykjavík, 422 = Akureyri, 571 = Egilsstaðirin lentoasema, 990 = Keflavíkin lentoasema.\", \"notes\": \"Mainitse lähde: Veðurstofa Íslands.\", \"endpoints\": { \"obs\": { \"name\": \"Havainnot\", \"description\": \"Yksi rivi per asema viimeisimmällä havainnolla.\", \"params\": { \"ids\": { \"label\": \"Asemanumerot (puolipisteet välissä)\" }, \"params\": { \"label\": \"Parametrit (puolipisteet välissä, tyhjä antaa kaikki)\" }, \"lang\": { \"label\": \"Kieli\", \"options\": { \"is\": \"Islanti\", \"en\": \"Englanti\" } } } } }, \"dataset\": { \"obs\": \"Veðurstofa havainnot {ids}\" } },\n    \"is\": { \"name\": \"Veðurstofa Íslands: veðurathuganir\", \"publisher\": \"Veðurstofa Íslands\", \"description\": \"Nýjustu athuganir frá veðurstöðvum Íslands: hiti (T), vindhraði (F), vindátt (D), hviður (FX, FG), úrkoma (R), veður (W) og skyggni (V). Stöðvanúmer má finna á vedur.is undir Stöðvar; 1 = Reykjavík, 422 = Akureyri, 571 = Egilsstaðaflugvöllur, 990 = Keflavíkurflugvöllur.\", \"notes\": \"Tilgreindu heimild: Veðurstofa Íslands.\", \"endpoints\": { \"obs\": { \"name\": \"Athuganir\", \"description\": \"Ein röð fyrir hverja stöð með nýjustu athugun.\", \"params\": { \"ids\": { \"label\": \"Stöðvanúmer (semikommur á milli)\" }, \"params\": { \"label\": \"Breytur (semikommur á milli, autt gefur allar)\" }, \"lang\": { \"label\": \"Tungumál\", \"options\": { \"is\": \"Íslenska\", \"en\": \"Enska\" } } } } }, \"dataset\": { \"obs\": \"Veðurstofa athuganir {ids}\" } }\n  }\n}\n");
